arguments.command:
cd /tmp/sv-755c474c1a02424bbaa4462fb3397e5d && \
# Find the nearest named function for these addresses using nm
aarch64-linux-gnu-nm -C libmonosgen-2.0.so.dbg 2>/dev/null | sort | awk -v a1=0x2f4b20 -v a2=0x2f4c84 '
{
  addr = strtonum("0x" $1)
  if (addr <= strtonum(a1)) { name1 = $3; off1 = strtonum(a1) - addr }
  if (addr <= strtonum(a2)) { name2 = $3; off2 = strtonum(a2) - addr }
}
END {
  printf "0x2f4b20 -> %s+0x%x\n", name1, off1
  printf "0x2f4c84 -> %s+0x%x\n", name2, off2
}' 2>&1 || \
# Fallback: use readelf
readelf -sW libmonosgen-2.0.so.dbg 2>/dev/null | awk '$2 != "" && strtonum("0x"$2) > 0' | sort -k2 | awk '
{
  addr = strtonum("0x" $2)
  size = strtonum("0x" $3) + 0
  if (addr <= 0x2f4b20 && addr + size > 0x2f4b20) print "0x2f4b20 in " $8 " +" (0x2f4b20 - addr)
  if (addr <= 0x2f4c84 && addr + size > 0x2f4c84) print "0x2f4c84 in " $8 " +" (0x2f4c84 - addr)
}' 2>&1

